UPDATE body_data
weight = #{weight}, bmi = #{bmi}, source = #{source}, remark = #{remark}, update_time = NOW()
WHERE id = #{id}

mapper.select:
SELECT 
FROM body_data
WHERE user_id = #{userId}
  AND record_date BETWEEN #{startDate} AND #{endDate}
ORDER BY record_date ASC

SELECT 
FROM body_data
WHERE user_id = #{userId}
ORDER BY record_date DESC
LIMIT #{limit}
